catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || !newValue) {
        g_form.setValue('email_preview', '');
        g_form.setValue('email', '');
        return;
    }

    // Clean and normalize the input
    var username = newValue.replace(/\s/g, '').trim();

    // Debug output (remove in prod)
    console.log("Username input: [" + username + "]");

    // Basic validation: letters, numbers, dot, underscore
    var allowedRegex = /^[a-zA-Z0-9._]+$/;
    if (!allowedRegex.test(username)) {
       g_form.addErrorMessage('Only letters, numbers, dots (.) and underscores (_) are allowed.');
        g_form.setValue('email_preview', '');
        g_form.setValue('email', '');
        return;
    }

    // No starting or ending with dot/underscore
    if (/^[._]|[._]$/.test(username)) {
        g_form.addErrorMessage('Email username cannot start or end with a dot or underscore.');
        g_form.setValue('email_preview', '');
        g_form.setValue('email', '');
        return;
    }

    // If everything is valid, set the final email
    var fullEmail = username + '@virtuxient.com';
    // g_form.setValue('email_preview', fullEmail);
    g_form.setValue('email', fullEmail);
}
